    def _prefer_ollama_profile_from_tags(self):
        if self._has_non_ollama_user_profiles():
            return
        tags = list_ollama_models_cached(self.ollama_base)
        if tags:
            self.ollama_env_tags = list(tags)
        elif self.ollama_env_tags:
            tags = list(self.ollama_env_tags)
        if not tags:
            return
        target_pid = ""
        for pid, profile in self.user_model_profiles.items():
            if str(profile.get("provider", "")).lower() == "ollama":
                target_pid = pid
                break
        if not target_pid:
            target_pid = "ollama"
            n = 2
            while target_pid in self.user_model_profiles:
                target_pid = f"ollama-{n}"
                n += 1
            self.user_model_profiles[target_pid] = {
                "id": target_pid,
                "provider": "ollama",
                "label": "Ollama",
                "model": tags[0],
                "base_url": self.ollama_base,
                "temperature": 0.2,
                "request_timeout": DEFAULT_REQUEST_TIMEOUT,
                "capabilities": infer_model_multimodal_capabilities("ollama", tags[0]),
                "media_endpoints": {},
                "source": "startup-autodetect",
            }
        profile = dict(self.user_model_profiles[target_pid])
        current = str(profile.get("model", "")).strip()
        profile["model"] = current if current in tags else tags[0]
        profile["base_url"] = self.ollama_base
        profile["selection"] = f"{target_pid}::{profile.get('model','')}"
        self.user_model_profiles[target_pid] = profile
        self.user_active_profile_id = target_pid

    def _load_user_prefs(self) -> bool:
        loaded = False
        if self.user_prefs_path.exists():
            raw = self.crypto.read_json(self.user_prefs_path, {})
            self.user_language = normalize_ui_language(raw.get("ui_language", self.user_language))
            self.read_context_policy = normalize_read_context_policy(
                raw.get("read_context_policy", getattr(self, "read_context_policy", DEFAULT_READ_CONTEXT_POLICY))
            )
            self.tool_memory_policy = normalize_tool_memory_policy(
                raw.get(
                    "tool_memory_policy",
                    raw.get("read_context_policy", getattr(self, "tool_memory_policy", DEFAULT_TOOL_MEMORY_POLICY)),
                )
            )
            raw_auto_task_level_ceiling = extract_auto_task_level_ceiling_setting(raw)
            self.auto_task_level_ceiling = normalize_auto_task_level_ceiling(
                raw_auto_task_level_ceiling
                if raw_auto_task_level_ceiling is not None
                else getattr(self, "auto_task_level_ceiling", DEFAULT_AUTO_TASK_LEVEL_CEILING)
            )
            cfg_l2_todo_policy = extract_l2_todo_policy_setting(raw)
            if cfg_l2_todo_policy is not None:
                self.l2_todo_policy = normalize_l2_todo_policy(cfg_l2_todo_policy)
            if _single_no_plan_todo_setting_present(raw):
                _single_todo_enabled, _single_todo_prompt = extract_single_no_plan_todo_settings(raw)
                self.single_no_plan_todo_enabled = bool(_single_todo_enabled)
                self.single_no_plan_todo_prompt = str(_single_todo_prompt or "").strip()
            if not bool(getattr(self, "web_search_setting_locked", False)) and "web_search_enabled" in raw:
                self.web_search_enabled = _to_bool_like(
                    raw.get("web_search_enabled"),
                    default=getattr(self, "web_search_enabled", DEFAULT_WEB_SEARCH_ENABLED),
                )
            if not bool(getattr(self, "user_memory_setting_locked", False)):
                raw_user_memory_mode = extract_user_memory_mode_setting(raw)
                if raw_user_memory_mode is not None:
                    self.user_memory_mode = normalize_user_memory_mode(raw_user_memory_mode)
            self.global_llm_config_revision = str(raw.get("global_llm_config_revision", "") or "")
            self.global_llm_config_source = str(raw.get("global_llm_config_source", "") or "")
            self.collaboration_llm_independent = bool(
                raw.get("collaboration_llm_independent", False)
            )
            self.collaboration_llm_source_revision = str(
                raw.get("collaboration_llm_source_revision", "") or ""
            )
            self.collaboration_llm_source_user_id = str(
                raw.get("collaboration_llm_source_user_id", "") or ""
            )
            self.collaboration_llm_source_kind = str(
                raw.get("collaboration_llm_source_kind", "") or ""
            )
            profiles = raw.get("model_profiles", {})
            if isinstance(profiles, dict) and profiles:
                for k, v in profiles.items():
                    if not isinstance(v, dict):
                        continue
                    pid = sanitize_profile_id(str(k))
                    row = dict(v)
                    row["id"] = pid
                    row["selection"] = f"{pid}::{row.get('model','')}"
                    self.user_model_profiles[pid] = row
                active = sanitize_profile_id(str(raw.get("active_profile_id", "")))
                if active in self.user_model_profiles:
                    self.user_active_profile_id = active
                loaded = bool(self.user_model_profiles)
        if not self.user_model_profiles:
            self.user_model_profiles, self.user_active_profile_id = self._profiles_from_config(self.default_llm_config)
        self._ensure_user_ollama_profile()
        # Do not probe Ollama while the initial session page is loading.  The
        # catalog path still discovers tags on demand and keeps this fallback
        # profile runnable with the configured model in the meantime.
        if self.user_active_profile_id not in self.user_model_profiles:
            self.user_active_profile_id = next(iter(self.user_model_profiles.keys()))
        self._ensure_user_active_runnable()
        active = self._active_profile()
        self._sync_ollama_defaults(active)
        self.thinking = False
        self._persist_user_prefs()
        return loaded

    def _preflight_user_ollama_profile(self):
        profile = self.user_model_profiles.get(self.user_active_profile_id, {})
        if str(profile.get("provider", "ollama")).lower() != "ollama":
            return
        base = str(profile.get("base_url", self.ollama_base) or self.ollama_base)
        tags = list_ollama_models_cached(base)
        if tags:
            self.ollama_env_tags = list(tags)
        elif self.ollama_env_tags:
            tags = list(self.ollama_env_tags)
        if not tags:
            return
        current = str(profile.get("model", "") or self.model)
        picked = current if current in tags else tags[0]
        profile["base_url"] = base
        profile["model"] = picked
        profile["selection"] = f"{self.user_active_profile_id}::{picked}"
        self.user_model_profiles[self.user_active_profile_id] = profile

    def _set_session_profile(self, sess: SessionState, profile_id: str, profile: dict):
        row = dict(profile)
        row["id"] = profile_id
        row["selection"] = f"{profile_id}::{row.get('model','')}"
        if not sess._profile_is_runnable(row):
            provider = str(row.get("provider", "") or "unknown")
            model = str(row.get("model", "") or "")
            raise ValueError(
                f"profile '{profile_id}' is not runnable (provider={provider}, model={model or '(empty)'})"
            )
        sess.model_profiles[profile_id] = row
        sess.active_profile_id = profile_id
        sess.failed_selections = []
        sess._apply_active_profile()
        sess.updated_at = now_ts()
        sess._persist()

    def _apply_user_defaults_to_session(
        self,
        sess: SessionState,
        *,
        clear_cap_cache: bool = False,
        persist: bool = True,
    ):
        sess.model_profiles = {}
        for pid, profile in self.user_model_profiles.items():
            row = dict(profile)
            row["id"] = pid
            row["selection"] = f"{pid}::{row.get('model','')}"
            sess.model_profiles[pid] = row
        preferred = ""
        if self.user_active_profile_id in sess.model_profiles:
            candidate = dict(sess.model_profiles.get(self.user_active_profile_id, {}))
            if sess._profile_is_runnable(candidate):
                preferred = self.user_active_profile_id
        if not preferred:
            for pid, profile in sess.model_profiles.items():
                if sess._profile_is_runnable(profile):
                    preferred = pid
                    break
        if preferred:
            sess.active_profile_id = preferred
        sess.failed_selections = []
        if clear_cap_cache:
            sess.multimodal_capability_cache = {}
            sess.ollama.clear_probe_cache()
        sess._set_ui_language(self.user_language, relabel_todos=True)
        sess.auto_model_switch = bool(self.auto_model_switch)
        sess.arbiter_enabled = bool(self.arbiter_enabled)
        sess.arbiter_model = str(self.arbiter_model or "").strip()
        sess.arbiter_timeout_seconds = max(
            0.2,
            min(15.0, float(self.arbiter_timeout_seconds or ARBITER_DEFAULT_TIMEOUT_SECONDS)),
        )
        sess.arbiter_max_tokens = max(24, min(256, int(self.arbiter_max_tokens or ARBITER_DEFAULT_MAX_TOKENS)))
        sess.arbiter_temperature = max(
            0.0,
            min(1.0, float(self.arbiter_temperature if self.arbiter_temperature is not None else ARBITER_DEFAULT_TEMPERATURE)),
        )
        sess.execution_mode = normalize_execution_mode(self.execution_mode, default=EXECUTION_MODE_SYNC)
        sess.single_advance_prompt_enhance = bool(self.single_advance_prompt_enhance)
        sess.single_no_plan_todo_enabled = bool(
            getattr(self, "single_no_plan_todo_enabled", False)
        )
        sess.single_no_plan_todo_prompt = str(
            getattr(self, "single_no_plan_todo_prompt", "") or ""
        ).strip()[:6000]
        sess.read_context_policy = normalize_read_context_policy(
            getattr(self, "read_context_policy", DEFAULT_READ_CONTEXT_POLICY)
        )
        sess.tool_memory_policy = normalize_tool_memory_policy(
            getattr(self, "tool_memory_policy", getattr(self, "read_context_policy", DEFAULT_TOOL_MEMORY_POLICY))
        )
        sess.auto_task_level_ceiling = normalize_auto_task_level_ceiling(
            getattr(self, "auto_task_level_ceiling", DEFAULT_AUTO_TASK_LEVEL_CEILING)
        )
        sess.l2_todo_policy = normalize_l2_todo_policy(
            getattr(self, "l2_todo_policy", DEFAULT_L2_TODO_POLICY)
        )
        sess.web_search_enabled = bool(getattr(self, "web_search_enabled", DEFAULT_WEB_SEARCH_ENABLED))
        sess.user_memory_mode = normalize_user_memory_mode(getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE))
        sess.shell_command_timeout_seconds = normalize_timeout_seconds(
            self.shell_command_timeout_seconds,
            minimum=MIN_SHELL_COMMAND_TIMEOUT_SECONDS,
            maximum=MAX_SHELL_COMMAND_TIMEOUT_SECONDS,
            fallback=DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS,
        )
        sess.shell_timeout_mode = normalize_shell_timeout_mode(self.shell_timeout_mode)
        sess.shell_async_handoff_seconds = normalize_timeout_seconds(
            self.shell_async_handoff_seconds,
            minimum=MIN_SHELL_ASYNC_HANDOFF_SECONDS,
            maximum=MAX_SHELL_ASYNC_HANDOFF_SECONDS,
            fallback=DEFAULT_SHELL_ASYNC_HANDOFF_SECONDS,
        )
        sess._apply_active_profile()
        sess.updated_at = now_ts()
        if persist:
            sess._persist()

    def _sync_from_session(self, sess: SessionState, *, apply_to_all: bool):
        synced: dict[str, dict] = {}
        for pid, profile in sess.model_profiles.items():
            row = dict(profile)
            sid = sanitize_profile_id(str(pid))
            row["id"] = sid
            row["selection"] = f"{sid}::{row.get('model','')}"
            synced[sid] = row
        if synced:
            self.user_model_profiles = synced
        self._ensure_user_ollama_profile()
        active = sanitize_profile_id(str(sess.active_profile_id))
        if active in self.user_model_profiles:
            self.user_active_profile_id = active
        elif self.user_model_profiles:
            self.user_active_profile_id = next(iter(self.user_model_profiles.keys()))
        self._ensure_user_active_runnable()
        active_profile = self._active_profile()
        self._sync_ollama_defaults(active_profile)
        self.thinking = False
        self.user_language = normalize_ui_language(getattr(sess, "ui_language", self.user_language))
        self.single_no_plan_todo_enabled = bool(
            getattr(sess, "single_no_plan_todo_enabled", getattr(self, "single_no_plan_todo_enabled", False))
        )
        self.single_no_plan_todo_prompt = str(
            getattr(sess, "single_no_plan_todo_prompt", getattr(self, "single_no_plan_todo_prompt", ""))
            or ""
        ).strip()[:6000]
        self.read_context_policy = normalize_read_context_policy(
            getattr(sess, "read_context_policy", getattr(self, "read_context_policy", DEFAULT_READ_CONTEXT_POLICY))
        )
        self.tool_memory_policy = normalize_tool_memory_policy(
            getattr(
                sess,
                "tool_memory_policy",
                getattr(self, "tool_memory_policy", getattr(self, "read_context_policy", DEFAULT_TOOL_MEMORY_POLICY)),
            )
        )
        self.auto_task_level_ceiling = normalize_auto_task_level_ceiling(
            getattr(
                sess,
                "auto_task_level_ceiling",
                getattr(self, "auto_task_level_ceiling", DEFAULT_AUTO_TASK_LEVEL_CEILING),
            )
        )
        self.l2_todo_policy = normalize_l2_todo_policy(
            getattr(sess, "l2_todo_policy", getattr(self, "l2_todo_policy", DEFAULT_L2_TODO_POLICY))
        )
        if bool(getattr(self, "web_search_setting_locked", False)):
            set_web_search_enabled_on_runtime(sess, self.web_search_enabled, persist=True)
        else:
            self.web_search_enabled = bool(
                getattr(sess, "web_search_enabled", getattr(self, "web_search_enabled", DEFAULT_WEB_SEARCH_ENABLED))
            )
        if bool(getattr(self, "user_memory_setting_locked", False)):
            sess.user_memory_mode = normalize_user_memory_mode(getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE))
        else:
            self.user_memory_mode = normalize_user_memory_mode(
                getattr(sess, "user_memory_mode", getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE))
            )
        self._persist_user_prefs()
        if not apply_to_all:
            return
        for other in self.sessions.values():
            if other.id == sess.id:
                continue
            self._apply_user_defaults_to_session(other, clear_cap_cache=True)

    def prepare_user_intent_for_session(self, sess: SessionState, content: str) -> dict:
        mode = normalize_user_memory_mode(getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE))
        if mode == "off":
            sess.user_memory_mode = "off"
            sess.user_profile_capsule = ""
            sess.user_profile_capsule_meta = {"mode": "off", "memory_count": 0}
            return {"ok": True, "mode": "off", "capsule_chars": 0, "memory_count": 0}
        try:
            out = self.user_intent_profiler.prepare_session(sess, content, mode)
            sess.user_memory_mode = mode
            sess.updated_at = now_ts()
            # The immediately following submit path persists the complete
            # request state. Avoid a second full encrypted state write here.
            return out
        except Exception as exc:
            sess.user_profile_capsule = ""
            sess.user_profile_capsule_meta = {"mode": mode, "error": trim(str(exc), 160)}
            return {"ok": False, "mode": mode, "error": trim(str(exc), 200)}

    def capture_user_memory_from_session(self, sess: SessionState) -> dict:
        mode = normalize_user_memory_mode(getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE))
        if mode == "off":
            return {"ok": True, "skipped": True, "mode": "off"}
        try:
            return self.user_memory_store.capture_session(sess, mode=mode)
        except Exception as exc:
            return {"ok": False, "error": trim(str(exc), 220)}

    def user_memory_payload(self, *, limit: int = 80) -> dict:
        payload = self.user_memory_store.payload(limit=limit)
        payload["user_memory_mode"] = normalize_user_memory_mode(getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE))
        payload["setting_locked"] = bool(getattr(self, "user_memory_setting_locked", False))
        return payload

    def user_memory_export_payload(self) -> dict:
        payload = self.user_memory_store.export_payload()
        payload["user_memory_mode"] = normalize_user_memory_mode(getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE))
        return payload

    def clear_user_memory(self) -> dict:
        return self.user_memory_store.clear()

    def set_user_memory_mode(self, mode: str) -> dict:
        if bool(getattr(self, "user_memory_setting_locked", False)):
            return {
                "ok": False,
                "locked": True,
                "user_memory_mode": normalize_user_memory_mode(getattr(self, "user_memory_mode", DEFAULT_USER_MEMORY_MODE)),
                "error": "user memory mode is locked by startup argument",
            }
        self.user_memory_mode = normalize_user_memory_mode(mode)
        for sess in list(self.sessions.values()):
            try:
                sess.user_memory_mode = self.user_memory_mode
                if self.user_memory_mode == "off":
                    sess.user_profile_capsule = ""
                    sess.user_profile_capsule_meta = {"mode": "off", "memory_count": 0}
                sess.updated_at = now_ts()
                sess._persist()
            except Exception:
                pass
        self._persist_user_prefs()
        return {"ok": True, "user_memory_mode": self.user_memory_mode}

    @staticmethod
    def _normalize_workspace_id(value: object, fallback: str) -> str:
        default = trim(str(fallback or "").strip(), 160)
        candidate = trim(str(value or "").strip(), 160)
        if (
            not candidate
            or candidate in {".", ".."}
            or "/" in candidate
            or "\\" in candidate
            or "\x00" in candidate
        ):
            return default
        return candidate

    def _session_workspace_spec(self, session_id: str, workspace_id: object) -> tuple[str, Path | None]:
        sid = str(session_id or "").strip()
        wid = self._normalize_workspace_id(workspace_id, sid)
        if self.workspace_root is not None:
            return wid, self.workspace_root
        if wid == sid:
            return wid, None
        owner = self.root / wid
        try:
            owner.resolve(strict=False).relative_to(self.root.resolve(strict=False))
        except (OSError, ValueError):
            return sid, None
        if not owner.is_dir() or owner.is_symlink():
            return sid, None
        return wid, owner / "files"

    def _session_summary_from_disk(self, path: Path) -> dict:
        sid = str(path.name or "").strip()
        title = sid
        workspace_id = sid
        title_origin = ""
        title_revision = 0
        updated_at = 0.0
        created_at = 0.0
        message_count = 0
        ui_language = self.user_language
        kernel_version = ""
        meta = path / "meta.json"
        if meta.exists():
            try:
                raw = self.crypto.read_json(meta, {})
                if isinstance(raw, dict):
                    title = str(raw.get("title", sid) or sid)
                    workspace_id = self._normalize_workspace_id(raw.get("workspace_id"), sid)
                    title_origin = str(raw.get("title_origin", "") or "")
                    title_revision = max(0, int(raw.get("title_revision", 0) or 0))
                    created_at = float(raw.get("created_at", 0.0) or 0.0)
                    updated_at = float(raw.get("updated_at", 0.0) or 0.0)
                    message_count = max(0, int(raw.get("message_count", 0) or 0))
                    ui_language = normalize_ui_language(raw.get("ui_language", ui_language))
                    kernel_version = str(raw.get("kernel_version", "") or "")
            except Exception:
                pass
        if updated_at <= 0:
            try:
                state = path / "state.json"
                updated_at = float((state if state.exists() else path).stat().st_mtime)
            except Exception:
                updated_at = 0.0
        if created_at <= 0:
            try:
                state = path / "state.json"
                if state.exists():
                    raw_state = self.crypto.read_json(state, {})
                    if isinstance(raw_state, dict):
                        created_at = float(raw_state.get("created_at", 0.0) or 0.0)
            except Exception:
                created_at = 0.0
        if created_at <= 0:
            created_at = float(updated_at or 0.0)
        return {
            "id": sid,
            "workspace_id": workspace_id,
            "title": title,
            "title_origin": title_origin,
            "title_revision": title_revision,
            "created_at": float(created_at or 0.0),
            "running": False,
            "degraded": False,
            "recovered_at": 0.0,
            "recovered_reason": "",
            "ui_language": ui_language,
            "updated_at": float(updated_at or 0.0),
            "message_count": int(message_count),
            "kernel_version": kernel_version,
            "loaded": False,
        }

    def _make_session_state(self, sid: str, title: str, workspace_id: str = "") -> SessionState:
        kernel_version = ""
        if self.kernel_registry is not None:
            try:
                kernel_version = self.kernel_registry.choose_version(self.user_id, sid)
            except Exception:
                kernel_version = ""
        resolved_workspace_id, session_workspace_root = self._session_workspace_spec(
            sid, workspace_id
        )
        sess = SessionState(
                session_id=sid,
                title=title,
                root=self.root,
                ollama_base=self.ollama_base,
                model=self.model,
                skills_root=self.skills_root,
                crypto=self.crypto,
                repo_root=self.repo_root,
                thinking=self.thinking,
                default_llm_config=self.default_llm_config,
                context_token_limit=self.context_token_limit,
                context_limit_locked=self.context_limit_locked,
                max_rounds=self.max_rounds,
                max_run_seconds=self.max_run_seconds,
                shell_command_timeout_seconds=self.shell_command_timeout_seconds,
                auto_task_level_ceiling=self.auto_task_level_ceiling,
                l2_todo_policy=self.l2_todo_policy,
                auto_model_switch=self.auto_model_switch,
                arbiter_enabled=self.arbiter_enabled,
                arbiter_model=self.arbiter_model,
                arbiter_timeout_seconds=self.arbiter_timeout_seconds,
                arbiter_max_tokens=self.arbiter_max_tokens,
                arbiter_temperature=self.arbiter_temperature,
                execution_mode=self.execution_mode,
                max_output_tokens=self.max_output_tokens,
                web_search_enabled=self.web_search_enabled,
                ui_language=self.user_language,
                js_lib_root=self.js_lib_root,
                js_lib_download_enabled=self.js_lib_download_enabled,
                owner_user_id=self.user_id,
                upload_callback=self.upload_callback,
                run_finished_callback=self.run_finished_callback,
                reference_prepare_callback=self.reference_prepare_callback,
                query_code_library_callback=self.query_code_library_callback,
                query_knowledge_library_callback=self.query_knowledge_library_callback,
                rag_remember_callback=self.rag_remember_callback,
                code_library_root=self.code_library_root,
                code_library_status_callback=self.code_library_status_callback,
                knowledge_library_root=self.knowledge_library_root,
                knowledge_library_status_callback=self.knowledge_library_status_callback,
                mcp_manager=getattr(self, "mcp_manager", None),
                workspace_root=session_workspace_root,
                workspace_id=resolved_workspace_id,
                collaboration_context=self.collaboration_context,
                collaboration_context_provider=self.collaboration_context_provider,
                collaboration_write_coordinator=self.collaboration_write_coordinator,
                shell_timeout_mode=self.shell_timeout_mode,
                shell_async_handoff_seconds=self.shell_async_handoff_seconds,
                process_manager=self.process_manager,
                deferred_start_prepare_callback=self.prepare_user_intent_for_session,
                summary_update_callback=self._on_session_summary,
                kernel_version=kernel_version,
                kernel_runtime=self.kernel_runtime,
                skills_snapshot=self.skills_snapshot,
            )
        sess.workspace_metadata_callback = self._workspace_metadata_for_session
        sess.set_telemetry_callback(self.telemetry_callback)
        desired_mode = normalize_execution_mode(self.execution_mode, default=EXECUTION_MODE_SYNC)
        if normalize_execution_mode(getattr(sess, "execution_mode", ""), default=desired_mode) != desired_mode:
            sess.execution_mode = desired_mode
            sess.updated_at = now_ts()
            sess._persist()
        if bool(getattr(self, "force_global_defaults_on_load", False)):
            self._apply_user_defaults_to_session(sess, clear_cap_cache=True)
        elif not sess.model_profiles:
            self._apply_user_defaults_to_session(sess)
        return sess

    def _schedule_session_catalog_rebuild_locked(self) -> None:
        if bool(getattr(self, "_session_catalog_rebuild_pending", False)):
            return
        self._session_catalog_rebuild_pending = True

        def worker() -> None:
            time.sleep(0.2)
            for _ in range(3):
                with self.lock:
                    revision = int(getattr(self, "catalog_revision", 0) or 0)
                    rows = [dict(row) for row in self.session_index.values() if isinstance(row, dict)]
                rows.sort(key=lambda row: float(row.get("updated_at", 0.0) or 0.0), reverse=True)
                with self.lock:
                    if revision == int(getattr(self, "catalog_revision", 0) or 0):
                        self._session_catalog_cache = rows
                        self._session_catalog_cache_revision = revision
                        self._session_catalog_recent = {}
                        self._session_catalog_deleted_ids = set()
                        self._session_catalog_rebuild_pending = False
                        return
                time.sleep(0.1)
            with self.lock:
                self._session_catalog_rebuild_pending = False

        threading.Thread(
            target=worker,
            name=f"session-catalog-{getattr(self, 'user_id', '') or 'local'}",
            daemon=True,
        ).start()

    def _session_catalog_changed_locked(self, session_id: str = "", *, deleted: bool = False) -> None:
        self.catalog_revision = max(0, int(getattr(self, "catalog_revision", 0) or 0)) + 1
        self._session_index_dirty = True
        sid = str(session_id or "").strip()
        if not sid:
            self._session_catalog_cache_revision = -1
            self._session_catalog_recent = {}
            self._session_catalog_deleted_ids = set()
            return
        if int(getattr(self, "_session_catalog_cache_revision", -1) or -1) < 0:
            return
        recent = getattr(self, "_session_catalog_recent", None)
        if not isinstance(recent, dict):
            recent = {}
            self._session_catalog_recent = recent
        deleted_ids = getattr(self, "_session_catalog_deleted_ids", None)
        if not isinstance(deleted_ids, set):
            deleted_ids = set()
            self._session_catalog_deleted_ids = deleted_ids
        if deleted:
            recent.pop(sid, None)
            deleted_ids.add(sid)
        else:
            deleted_ids.discard(sid)
            row = self.session_index.get(sid)
            if isinstance(row, dict):
                recent[sid] = dict(row)
        if len(recent) + len(deleted_ids) >= SESSION_CATALOG_RECENT_MAX:
            self._schedule_session_catalog_rebuild_locked()

    def _session_index_summary_payload(self, summary: dict) -> dict:
        allowed = {
            "id", "workspace_id", "title", "title_origin", "title_revision", "running", "degraded", "recovered_at",
            "recovered_reason", "ui_language", "created_at", "updated_at", "message_count", "kernel_version",
        }
        return {key: value for key, value in dict(summary or {}).items() if key in allowed}

    def _session_index_payload_locked(self) -> dict:
        return {
            "version": 1,
            "catalog_revision": int(self.catalog_revision or 0),
            "sessions": {
                str(session_id): self._session_index_summary_payload(summary)
                for session_id, summary in self.session_index.items()
                if isinstance(summary, dict)
            },
        }

    def _write_session_index_payload(self, payload: dict) -> bool:
        revision = max(0, int(payload.get("catalog_revision", 0) or 0)) if isinstance(payload, dict) else 0
        if not hasattr(self, "_session_index_write_lock"):
            self._session_index_write_lock = threading.Lock()
        try:
            with self._session_index_write_lock:
                last_written = int(getattr(self, "_session_index_written_revision", -1) or -1)
                if revision < last_written:
                    return True
                self.crypto.write_json(self.session_index_path, payload)
                self._session_index_written_revision = revision
            return True
        except Exception:
            return False

    def _session_index_journal_entries(self) -> list[tuple[dict, str]]:
        path = getattr(self, "session_index_journal_path", None)
        if not isinstance(path, Path) or not path.exists():
            return []
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except Exception:
            return []
        entries: list[tuple[dict, str]] = []
        for line in lines:
            raw_line = str(line or "").strip()
            if not raw_line:
                continue
            try:
                record = json.loads(self.crypto.decrypt_text(raw_line))
            except Exception:
                continue
            if isinstance(record, dict):
                entries.append((record, raw_line))
        return entries

    def _append_session_index_journal_record_locked(self, record: dict) -> bool:
        path = getattr(self, "session_index_journal_path", None)
        if not isinstance(path, Path) or not getattr(self, "crypto", None):
            return False
        if not hasattr(self, "_session_index_write_lock"):
            self._session_index_write_lock = threading.Lock()
        try:
            line = self.crypto.encrypt_text(json_dumps(record)) + "\n"
            path.parent.mkdir(parents=True, exist_ok=True)
            with self._session_index_write_lock:
                with path.open("a", encoding="utf-8") as fileobj:
                    fileobj.write(line)
                    fileobj.flush()
                    self.crypto._fsync_json_file(fileobj)
            self._session_index_journal_records = max(
                0, int(getattr(self, "_session_index_journal_records", 0) or 0)
            ) + 1
            self._session_index_journal_bytes = max(
                0, int(getattr(self, "_session_index_journal_bytes", 0) or 0)
            ) + len(line.encode("utf-8"))
            return True
        except Exception:
            return False

    def _queue_session_index_change_locked(self, session_id: str, *, deleted: bool = False) -> None:
        sid = str(session_id or "").strip()
        if not sid:
            return
        pending = getattr(self, "_session_index_pending_changes", None)
        if not isinstance(pending, dict):
            pending = {}
            self._session_index_pending_changes = pending
        revision = int(getattr(self, "catalog_revision", 0) or 0)
        record = {
            "version": 1,
            "revision": revision,
            "op": "delete" if deleted else "upsert",
            "session_id": sid,
        }
        if not deleted:
            row = self.session_index.get(sid)
            if not isinstance(row, dict):
                return
            record["summary"] = self._session_index_summary_payload(row)
        pending[sid] = record
        self._schedule_session_index_persist_locked()

    def _rewrite_session_index_journal_locked(self, through_revision: int) -> None:
        path = getattr(self, "session_index_journal_path", None)
        if not isinstance(path, Path):
            return
        retained = [
            line
            for record, line in self._session_index_journal_entries()
            if int(record.get("revision", 0) or 0) > int(through_revision or 0)
        ]
        if not hasattr(self, "_session_index_write_lock"):
            self._session_index_write_lock = threading.Lock()
        with self._session_index_write_lock:
            if not retained:
                try:
                    path.unlink(missing_ok=True)
                except Exception:
                    pass
            else:
                tmp = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
                try:
                    with tmp.open("w", encoding="utf-8") as fileobj:
                        fileobj.write("\n".join(retained) + "\n")
                        fileobj.flush()
                        self.crypto._fsync_json_file(fileobj)
                    os.replace(tmp, path)
                finally:
                    try:
                        tmp.unlink(missing_ok=True)
                    except Exception:
                        pass
        self._session_index_journal_records = len(retained)
        self._session_index_journal_bytes = sum(len(line.encode("utf-8")) + 1 for line in retained)

    def _compact_session_index_snapshot(self) -> bool:
        with self.lock:
            payload = self._session_index_payload_locked()
            revision = int(payload.get("catalog_revision", 0) or 0)
        if not self._write_session_index_payload(payload):
            return False
        with self.lock:
            self._rewrite_session_index_journal_locked(revision)
            self._session_index_dirty = bool(
                int(getattr(self, "catalog_revision", 0) or 0) > revision
                or getattr(self, "_session_index_pending_changes", {})
            )
        return True

    def _persist_session_index_change_now_locked(self, session_id: str, *, deleted: bool = False) -> None:
        sid = str(session_id or "").strip()
        pending = getattr(self, "_session_index_pending_changes", None)
        if isinstance(pending, dict):
            pending.pop(sid, None)
        journal_count = max(0, int(getattr(self, "_session_index_journal_records", 0) or 0))
        if len(self.session_index) <= SESSION_INDEX_SYNC_SNAPSHOT_MAX and journal_count == 0:
            self._persist_session_index_now_locked()
            return
        revision = int(getattr(self, "catalog_revision", 0) or 0)
        record = {
            "version": 1,
            "revision": revision,
            "op": "delete" if deleted else "upsert",
            "session_id": sid,
        }
        if not deleted:
            row = self.session_index.get(sid)
            if isinstance(row, dict):
                record["summary"] = self._session_index_summary_payload(row)
        if not self._append_session_index_journal_record_locked(record):
            self._persist_session_index_now_locked()
            return
        self._session_index_dirty = False
        if (
            int(getattr(self, "_session_index_journal_records", 0) or 0) >= SESSION_INDEX_JOURNAL_COMPACT_RECORDS
            or int(getattr(self, "_session_index_journal_bytes", 0) or 0) >= SESSION_INDEX_JOURNAL_COMPACT_BYTES
        ):
            self._session_index_compact_requested = True
            self._schedule_session_index_persist_locked()

    def _persist_session_index_now_locked(self) -> None:
        payload = self._session_index_payload_locked()
        if self._write_session_index_payload(payload):
            self._rewrite_session_index_journal_locked(int(payload.get("catalog_revision", 0) or 0))
            self._session_index_dirty = False
            return
        self._session_index_compact_requested = True
        self._schedule_session_index_persist_locked()

    def _schedule_session_index_persist_locked(self) -> None:
        self._session_index_dirty = True
        if not getattr(self, "session_index_path", None) or not getattr(self, "crypto", None):
            return
        if not hasattr(self, "_session_index_persist_lock"):
            self._session_index_persist_lock = threading.Lock()
        if not hasattr(self, "_session_index_persist_pending"):
            self._session_index_persist_pending = False
        with self._session_index_persist_lock:
            if self._session_index_persist_pending:
                return
            self._session_index_persist_pending = True

        def worker() -> None:
            while True:
                time.sleep(0.15)
                with self.lock:
                    pending = list(getattr(self, "_session_index_pending_changes", {}).values())
                    self._session_index_pending_changes = {}
                    append_ok = True
                    for record in pending:
                        append_ok = self._append_session_index_journal_record_locked(record) and append_ok
                    compact = not append_ok or bool(getattr(self, "_session_index_compact_requested", False)) or (
                        int(getattr(self, "_session_index_journal_records", 0) or 0) >= SESSION_INDEX_JOURNAL_COMPACT_RECORDS
                        or int(getattr(self, "_session_index_journal_bytes", 0) or 0) >= SESSION_INDEX_JOURNAL_COMPACT_BYTES
                    )
                    self._session_index_compact_requested = False
                    self._session_index_dirty = False
                compact_ok = True
                if compact:
                    compact_ok = self._compact_session_index_snapshot()
                with self.lock:
                    if not compact_ok:
                        self._session_index_dirty = True
                        self._session_index_compact_requested = True
                    if self._session_index_dirty or getattr(self, "_session_index_pending_changes", {}):
                        continue
                    with self._session_index_persist_lock:
                        self._session_index_persist_pending = False
                return

        threading.Thread(
            target=worker,
            name=f"session-index-{self.user_id or 'local'}",
            daemon=True,
        ).start()

    def _sync_workspace_metadata_locked(self, workspace_id: str) -> dict:
        metadata = {}
        for row_id, raw in self.session_index.items():
            if not isinstance(raw, dict):
                continue
            if self._normalize_workspace_id(raw.get("workspace_id"), row_id) != str(workspace_id or ""):
                continue
            loaded = self.sessions.get(row_id)
            created = float(
                (getattr(loaded, "created_at", 0.0) if loaded is not None else 0.0)
                or raw.get("created_at", 0.0)
                or raw.get("updated_at", 0.0)
                or 0.0
            )
            title = str(
                getattr(loaded, "title", "") if loaded is not None else raw.get("title", row_id)
            ).strip() or row_id
            prior = metadata.get("_first_created", 0.0)
            if "workspace_name" not in metadata or (created > 0 and (not prior or created < prior)):
                metadata.update(
                    {
                        "workspace_name": title,
                        "workspace_created_at": created,
                        "_first_created": created,
                    }
                )
        metadata.pop("_first_created", None)
        metadata["workspace_id"] = str(workspace_id or "")
        metadata["workspace_label"] = str(metadata.get("workspace_name", "") or workspace_id or "")
        for row_id, peer in self.session_index.items():
            if not isinstance(peer, dict) or self._normalize_workspace_id(peer.get("workspace_id"), row_id) != str(workspace_id or ""):
                continue
            peer.update(metadata)
        return metadata

    def _workspace_metadata_for_session(self, session_id: str) -> dict:
        """Return the stable display metadata shared by sessions in a workspace."""
        sid = str(session_id or "").strip()
        with self.lock:
            source = self.sessions.get(sid)
            source_row = self.session_index.get(sid, {})
            workspace_id = self._normalize_workspace_id(
                getattr(source, "workspace_id", "") if source is not None else source_row.get("workspace_id"),
                sid,
            )
            first_title = ""
            first_created = 0.0
            for row_id, raw in self.session_index.items():
                if not isinstance(raw, dict):
                    continue
                row_workspace = self._normalize_workspace_id(raw.get("workspace_id"), row_id)
                if row_workspace != workspace_id:
                    continue
                loaded = self.sessions.get(row_id)
                created = float(
                    (getattr(loaded, "created_at", 0.0) if loaded is not None else 0.0)
                    or raw.get("created_at", 0.0)
                    or raw.get("updated_at", 0.0)
                    or 0.0
                )
                title = str(
                    getattr(loaded, "title", "") if loaded is not None else raw.get("title", row_id)
                ).strip() or row_id
                if (
                    not first_title
                    or (created > 0 and (first_created <= 0 or created < first_created))
                ):
                    first_title, first_created = title, created
            name = first_title or str(getattr(source, "title", "") if source is not None else source_row.get("title", "") or sid)
            workspace_names: dict[str, str] = {}
            workspace_created: dict[str, float] = {}
            for row_id, raw in self.session_index.items():
                if not isinstance(raw, dict):
                    continue
                wid = self._normalize_workspace_id(raw.get("workspace_id"), row_id)
                loaded = self.sessions.get(row_id)
                created = float(
                    (getattr(loaded, "created_at", 0.0) if loaded is not None else 0.0)
                    or raw.get("created_at", 0.0)
                    or raw.get("updated_at", 0.0)
                    or 0.0
                )
                title = str(
                    getattr(loaded, "title", "") if loaded is not None else raw.get("title", row_id)
                ).strip() or row_id
                prior_created = workspace_created.get(wid, 0.0)
                if wid not in workspace_names or (created > 0 and (prior_created <= 0 or created < prior_created)):
                    workspace_names[wid] = title
                    workspace_created[wid] = created
            duplicate_count: dict[str, int] = {}
            for workspace_name in workspace_names.values():
                key = workspace_name.casefold()
                duplicate_count[key] = duplicate_count.get(key, 0) + 1
            label = name
            if duplicate_count.get(name.casefold(), 0) > 1 and first_created > 0:
                try:
                    label = f"{name} · {datetime.fromtimestamp(first_created).strftime('%Y-%m-%d')}"
                except Exception:
                    label = name
            return {
                "workspace_id": workspace_id,
                "workspace_name": name,
                "workspace_created_at": first_created,
                "workspace_label": label,
            }

    def _on_session_summary(self, summary: dict) -> None:
        if not isinstance(summary, dict):
            return
        session_id = str(summary.get("id", "") or "").strip()
        if not session_id:
            return
        with self.lock:
            if session_id not in self.session_index and session_id not in self.sessions:
                return
            previous = dict(self.session_index.get(session_id, {}))
            row = {
                **previous,
                "id": session_id,
                "workspace_id": self._normalize_workspace_id(
                    summary.get("workspace_id", previous.get("workspace_id")), session_id
                ),
                "title": str(summary.get("title", previous.get("title", session_id)) or session_id),
                "title_origin": str(summary.get("title_origin", previous.get("title_origin", "")) or ""),
                "title_revision": max(0, int(summary.get("title_revision", previous.get("title_revision", 0)) or 0)),
                "created_at": float(summary.get("created_at", previous.get("created_at", 0.0)) or 0.0),
                "running": bool(summary.get("running", previous.get("running", False))),
                "degraded": False,
                "recovered_at": float(summary.get("recovered_at", previous.get("recovered_at", 0.0)) or 0.0),
                "recovered_reason": str(summary.get("recovered_reason", previous.get("recovered_reason", "")) or ""),
                "ui_language": normalize_ui_language(summary.get("ui_language", previous.get("ui_language", self.user_language))),
                "updated_at": float(summary.get("updated_at", previous.get("updated_at", 0.0)) or 0.0),
                "message_count": max(0, int(summary.get("message_count", previous.get("message_count", 0)) or 0)),
                "kernel_version": str(summary.get("kernel_version", previous.get("kernel_version", "")) or ""),
                "loaded": True,
            }
            comparable_keys = (
                "workspace_id", "title", "title_origin", "title_revision", "running", "recovered_at", "recovered_reason",
                "ui_language", "created_at", "updated_at", "message_count",
                "kernel_version",
            )
            if all(previous.get(key) == row.get(key) for key in comparable_keys):
                self.session_index[session_id] = row
                self._sync_workspace_metadata_locked(row["workspace_id"])
                return
            self.session_index[session_id] = row
            self._sync_workspace_metadata_locked(row["workspace_id"])
            self._session_catalog_changed_locked(session_id)
            self._queue_session_index_change_locked(session_id)

    def _load_existing(self):
        loaded_index = False
        snapshot_revision = 0
        if self.session_index_path.exists():
            try:
                payload = self.crypto.read_json(self.session_index_path, {})
                raw_sessions = payload.get("sessions", {}) if isinstance(payload, dict) else {}
                if isinstance(raw_sessions, dict):
                    for session_id, raw in raw_sessions.items():
                        if not isinstance(raw, dict):
                            continue
                        sid = str(session_id or raw.get("id", "") or "").strip()
                        if not sid:
                            continue
                        self.session_index[sid] = {
                            "workspace_id": sid,
                            "title": sid,
                            "running": False,
                            "degraded": False,
                            "recovered_at": 0.0,
                            "recovered_reason": "",
                            "ui_language": self.user_language,
                            "updated_at": 0.0,
                            "created_at": 0.0,
                            "message_count": 0,
                            **dict(raw),
                            "id": sid,
                            "loaded": False,
                        }
                    self.catalog_revision = max(0, int(payload.get("catalog_revision", 0) or 0))
                    snapshot_revision = int(self.catalog_revision)
                    self._session_index_written_revision = int(self.catalog_revision)
                    loaded_index = True
            except Exception:
                loaded_index = False
        if not loaded_index:
            for path in sorted(self.root.glob("*")):
                if not path.is_dir() or (path / ".workspace_retained").exists():
                    continue
                sid = str(path.name or "").strip()
                if not sid:
                    continue
                self.session_index[sid] = self._session_summary_from_disk(path)
            if self.session_index:
                self.catalog_revision = 1
        journal_entries = self._session_index_journal_entries()
        for record, _line in journal_entries:
            revision = max(0, int(record.get("revision", 0) or 0))
            if revision <= snapshot_revision:
                continue
            sid = str(record.get("session_id", "") or "").strip()
            if not sid:
                continue
            if str(record.get("op", "") or "").strip().lower() == "delete":
                self.session_index.pop(sid, None)
            else:
                summary = record.get("summary", {})
                if not isinstance(summary, dict):
                    continue
                self.session_index[sid] = {
                    "workspace_id": sid,
                    "title": sid,
                    "running": False,
                    "degraded": False,
                    "recovered_at": 0.0,
                    "recovered_reason": "",
                    "ui_language": self.user_language,
                    "updated_at": 0.0,
                    "created_at": 0.0,
                    "message_count": 0,
                    **dict(summary),
                    "id": sid,
                    "loaded": False,
                }
            self.catalog_revision = max(int(self.catalog_revision or 0), revision)
        self._session_index_journal_records = len(journal_entries)
        try:
            self._session_index_journal_bytes = int(self.session_index_journal_path.stat().st_size)
        except Exception:
            self._session_index_journal_bytes = 0
        if not loaded_index and self.session_index:
            self._write_session_index_payload(self._session_index_payload_locked())
            self._rewrite_session_index_journal_locked(int(self.catalog_revision or 0))
        elif (
            self._session_index_journal_records >= SESSION_INDEX_JOURNAL_COMPACT_RECORDS
            or self._session_index_journal_bytes >= SESSION_INDEX_JOURNAL_COMPACT_BYTES
        ):
            self._session_index_compact_requested = True
            self._schedule_session_index_persist_locked()

    def _session_catalog_rows_locked(self) -> list[dict]:
        revision = int(getattr(self, "catalog_revision", 0) or 0)
        if int(getattr(self, "_session_catalog_cache_revision", -1) or -1) < 0:
            rows = [dict(row) for row in self.session_index.values() if isinstance(row, dict)]
            rows.sort(key=lambda row: float(row.get("updated_at", 0.0) or 0.0), reverse=True)
            self._session_catalog_cache = rows
            self._session_catalog_cache_revision = revision
            self._session_catalog_recent = {}
            self._session_catalog_deleted_ids = set()
        recent = getattr(self, "_session_catalog_recent", {})
        deleted_ids = getattr(self, "_session_catalog_deleted_ids", set())
        if not recent and not deleted_ids:
            return getattr(self, "_session_catalog_cache", [])
        recent_rows = [dict(row) for row in recent.values() if isinstance(row, dict)]
        recent_rows.sort(key=lambda row: float(row.get("updated_at", 0.0) or 0.0), reverse=True)
        recent_ids = {str(row.get("id", "") or "") for row in recent_rows}
        return recent_rows + [
            row
            for row in getattr(self, "_session_catalog_cache", [])
            if str(row.get("id", "") or "") not in recent_ids
            and str(row.get("id", "") or "") not in deleted_ids
        ]

    def _session_catalog_page_locked(self, offset: int, limit: int) -> tuple[list[dict], int]:
        if int(getattr(self, "_session_catalog_cache_revision", -1) or -1) < 0:
            self._session_catalog_rows_locked()
        off = max(0, int(offset or 0))
        lim = max(1, int(limit or SESSION_LIST_DEFAULT_LIMIT))
        recent = getattr(self, "_session_catalog_recent", {})
        deleted_ids = getattr(self, "_session_catalog_deleted_ids", set())
        recent_rows = [dict(row) for row in recent.values() if isinstance(row, dict)]
        recent_rows.sort(key=lambda row: float(row.get("updated_at", 0.0) or 0.0), reverse=True)
        recent_ids = {str(row.get("id", "") or "") for row in recent_rows}
        needed = off + lim
        merged: list[dict] = recent_rows[:needed]
        if len(merged) < needed:
            for row in getattr(self, "_session_catalog_cache", []):
                sid = str(row.get("id", "") or "")
                if sid in recent_ids or sid in deleted_ids:
                    continue
                merged.append(row)
                if len(merged) >= needed:
                    break
        return merged[off:needed], len(self.session_index)

    def _load_session_locked(self, session_id: str) -> SessionState | None:
        sid = str(session_id or "").strip()
        if not sid:
            return None
        existing = self.sessions.get(sid)
        if existing:
            return existing
        session_dir = self.root / sid
        if (
            not session_dir.exists()
            or not session_dir.is_dir()
            or (session_dir / ".workspace_retained").exists()
        ):
            return None
        summary = self.session_index.get(sid) or self._session_summary_from_disk(session_dir)
        title = str(summary.get("title", sid) or sid)
        sess = self._make_session_state(
            sid,
            title,
            self._normalize_workspace_id(summary.get("workspace_id"), sid),
        )
        self.sessions[sid] = sess
        self.session_index[sid] = {
            **summary,
            "workspace_id": str(getattr(sess, "workspace_id", sid) or sid),
            "title": str(getattr(sess, "title", title) or title),
            "title_origin": str(getattr(sess, "title_origin", summary.get("title_origin", "")) or ""),
            "title_revision": int(getattr(sess, "auto_title_revision", summary.get("title_revision", 0)) or 0),
            "created_at": float(getattr(sess, "created_at", summary.get("created_at", 0.0)) or 0.0),
            "running": bool(getattr(sess, "running", False)),
            "recovered_at": float(getattr(sess, "run_recovered_at", 0.0) or 0.0),
            "recovered_reason": str(getattr(sess, "run_recovered_reason", "") or ""),
            "ui_language": normalize_ui_language(getattr(sess, "ui_language", self.user_language)),
            "updated_at": float(getattr(sess, "updated_at", summary.get("updated_at", 0.0)) or 0.0),
            "message_count": int(self._session_message_count(sess)),
            "kernel_version": str(getattr(sess, "kernel_version", summary.get("kernel_version", "")) or ""),
            "loaded": True,
        }
        return sess

    def _session_message_count(self, sess: SessionState) -> int:
        try:
            if not bool(getattr(sess, "_ui_runtime_state_ready", False)):
                with sess.lock:
                    sess._ensure_ui_runtime_state_locked()
            return max(0, int(getattr(sess, "ui_message_count", 0) or 0))
        except Exception:
            return 0

    def create(
        self,
        title: str | None = None,
        *,
        title_origin: str | None = None,
        workspace_session_id: str = "",
    ) -> SessionState:
        with self.lock:
            sid = make_id("sess")
            name = title.strip() if title else sid
            source_id = str(workspace_session_id or "").strip()
            source = self._load_session_locked(source_id) if source_id else None
            if source_id and source is None:
                raise KeyError(source_id)
            workspace_id = (
                self._normalize_workspace_id(getattr(source, "workspace_id", ""), source.id)
                if source is not None
                else self._normalize_workspace_id(
                    self.collaboration_context.get("project_id") if self.workspace_root is not None else "",
                    sid,
                )
            )
            session_workspace_root = (
                self.workspace_root
                if self.workspace_root is not None
                else (source.files_root if source is not None else None)
            )
            kernel_version = ""
            if self.kernel_registry is not None:
                try:
                    kernel_version = self.kernel_registry.choose_version(self.user_id, sid)
                except Exception:
                    kernel_version = ""
            sess = SessionState(
                session_id=sid,
                title=name,
                root=self.root,
                ollama_base=self.ollama_base,
                model=self.model,
                skills_root=self.skills_root,
                crypto=self.crypto,
                repo_root=self.repo_root,
                thinking=self.thinking,
                default_llm_config=self.default_llm_config,
                context_token_limit=self.context_token_limit,
                context_limit_locked=self.context_limit_locked,
                max_rounds=self.max_rounds,
                max_run_seconds=self.max_run_seconds,
                shell_command_timeout_seconds=self.shell_command_timeout_seconds,
                auto_task_level_ceiling=self.auto_task_level_ceiling,
                l2_todo_policy=self.l2_todo_policy,
                auto_model_switch=self.auto_model_switch,
                arbiter_enabled=self.arbiter_enabled,
                arbiter_model=self.arbiter_model,
                arbiter_timeout_seconds=self.arbiter_timeout_seconds,
                arbiter_max_tokens=self.arbiter_max_tokens,
                arbiter_temperature=self.arbiter_temperature,
                execution_mode=self.execution_mode,
                max_output_tokens=self.max_output_tokens,
                web_search_enabled=self.web_search_enabled,
                ui_language=self.user_language,
                js_lib_root=self.js_lib_root,
                js_lib_download_enabled=self.js_lib_download_enabled,
                owner_user_id=self.user_id,
                upload_callback=self.upload_callback,
                run_finished_callback=self.run_finished_callback,
                reference_prepare_callback=self.reference_prepare_callback,
                query_code_library_callback=self.query_code_library_callback,
                query_knowledge_library_callback=self.query_knowledge_library_callback,
                rag_remember_callback=self.rag_remember_callback,
                code_library_root=self.code_library_root,
                code_library_status_callback=self.code_library_status_callback,
                knowledge_library_root=self.knowledge_library_root,
                knowledge_library_status_callback=self.knowledge_library_status_callback,
                mcp_manager=getattr(self, "mcp_manager", None),
                workspace_root=session_workspace_root,
                workspace_id=workspace_id,
                collaboration_context=self.collaboration_context,
                collaboration_context_provider=self.collaboration_context_provider,
                collaboration_write_coordinator=self.collaboration_write_coordinator,
                shell_timeout_mode=self.shell_timeout_mode,
                shell_async_handoff_seconds=self.shell_async_handoff_seconds,
                process_manager=self.process_manager,
                deferred_start_prepare_callback=self.prepare_user_intent_for_session,
                summary_update_callback=None,
                kernel_version=kernel_version,
                kernel_runtime=self.kernel_runtime,
                skills_snapshot=self.skills_snapshot,
                defer_initial_persist=True,
            )
            sess.workspace_metadata_callback = self._workspace_metadata_for_session
            requested_origin = str(title_origin or "").strip().lower()
            if requested_origin in {"default", "auto", "application", "manual", "legacy"}:
                sess.title_origin = requested_origin
            elif title:
                sess.title_origin = "default" if sess._is_default_session_title(name) else "manual"
            sess.set_telemetry_callback(self.telemetry_callback)
            self._apply_user_defaults_to_session(sess, persist=True)
            sess.summary_update_callback = self._on_session_summary
            self.sessions[sid] = sess
            self.session_index[sid] = {
                "id": sid,
                "workspace_id": str(getattr(sess, "workspace_id", sid) or sid),
                "title": str(getattr(sess, "title", name) or name),
                "title_origin": str(getattr(sess, "title_origin", "") or ""),
                "title_revision": int(getattr(sess, "auto_title_revision", 0) or 0),
                "created_at": float(getattr(sess, "created_at", 0.0) or 0.0),
                "running": bool(getattr(sess, "running", False)),
                "degraded": False,
                "recovered_at": float(getattr(sess, "run_recovered_at", 0.0) or 0.0),
                "recovered_reason": str(getattr(sess, "run_recovered_reason", "") or ""),
                "ui_language": normalize_ui_language(getattr(sess, "ui_language", self.user_language)),
                "updated_at": float(getattr(sess, "updated_at", now_ts()) or now_ts()),
                "message_count": int(self._session_message_count(sess)),
                "kernel_version": str(getattr(sess, "kernel_version", "") or ""),
                "loaded": True,
            }
            self._session_catalog_changed_locked(sid)
            self._persist_session_index_change_now_locked(sid)
            return sess

    def get(self, session_id: str) -> SessionState | None:
        with self.lock:
            return self._load_session_locked(session_id)

    def rename(self, session_id: str, title: str) -> SessionState:
        with self.lock:
            sess = self._load_session_locked(session_id)
            if not sess:
                raise KeyError(session_id)
        session_lock = getattr(sess, "lock", None)
        guard = session_lock if session_lock is not None else contextlib.nullcontext()
        with guard:
            sess.title = title.strip() or sess.id
            sess.title_origin = "manual"
            sess.last_auto_title_source = ""
            sess.auto_title_revision = int(getattr(sess, "auto_title_revision", 0) or 0) + 1
            sess.auto_title_refine_generation = int(getattr(sess, "auto_title_refine_generation", 0) or 0) + 1
            sess.auto_title_refine_pending = False
            sess.updated_at = now_ts()
            sess._persist()
        with self.lock:
            row = dict(self.session_index.get(sess.id, {}))
            row.update({
                "id": sess.id,
                "title": sess.title,
                "title_origin": "manual",
                "title_revision": int(getattr(sess, "auto_title_revision", 0) or 0),
                "updated_at": float(sess.updated_at or now_ts()),
                "message_count": int(self._session_message_count(sess)),
                "kernel_version": str(getattr(sess, "kernel_version", "") or ""),
                "loaded": True,
            })
            self.session_index[sess.id] = row
            self._session_catalog_changed_locked(sess.id)
            self._persist_session_index_change_now_locked(sess.id)
            emit = getattr(sess, "_emit", None)
            if callable(emit):
                payload = {
                    "summary": f"session renamed: '{trim(title, 36)}'",
                    "session_title": sess.title,
                    "title_origin": "manual",
                    "title_revision": int(getattr(sess, "auto_title_revision", 0) or 0),
                    "title_source": "manual",
                }
                metadata_callback = getattr(sess, "workspace_metadata_callback", None)
                if callable(metadata_callback):
                    try:
                        metadata = metadata_callback(sess.id)
                        if isinstance(metadata, dict):
                            payload.update(
                                {
                                    key: metadata[key]
                                    for key in (
                                        "workspace_id",
                                        "workspace_name",
                                        "workspace_created_at",
                                        "workspace_label",
                                    )
                                    if key in metadata
                                }
                            )
                    except Exception:
                        pass
                emit("status", payload)
            return sess

    def delete(self, session_id: str) -> bool:
        sid = str(session_id or "").strip()
        if not sid:
            return False
        with self.lock:
            sess = self.sessions.pop(sid, None)
            summary = dict(self.session_index.get(sid, {}))
            existed = bool(sess or sid in self.session_index or (self.root / sid).exists())
            workspace_id = self._normalize_workspace_id(
                getattr(sess, "workspace_id", "") if sess is not None else summary.get("workspace_id"),
                sid,
            )
            workspace_peers = [
                row_id
                for row_id, row in self.session_index.items()
                if row_id != sid
                and isinstance(row, dict)
                and self._normalize_workspace_id(row.get("workspace_id"), row_id) == workspace_id
            ]
            retain_workspace = bool(
                self.workspace_root is None and workspace_id == sid and workspace_peers
            )
            self.session_index.pop(sid, None)
            if existed:
                self._session_catalog_changed_locked(sid, deleted=True)
                self._persist_session_index_change_now_locked(sid, deleted=True)
        if not existed:
            return False
        if sess:
            # Note: sess.mcp is the SHARED global manager — never shut it down on
            # per-session delete (that would kill MCP for all other sessions).
            sess.interrupt()
        session_root = sess.root if sess is not None else self.root / sid
        if retain_workspace:
            session_root.mkdir(parents=True, exist_ok=True)
            for child in list(session_root.iterdir()):
                if child.name in {"files", ".workspace_retained"}:
                    continue
                try:
                    if child.is_dir() and not child.is_symlink():
                        shutil.rmtree(child, ignore_errors=True)
                    else:
                        child.unlink(missing_ok=True)
                except OSError:
                    pass
            try:
                (session_root / ".workspace_retained").write_text(workspace_id, encoding="utf-8")
            except OSError:
                pass
        else:
            shutil.rmtree(session_root, ignore_errors=True)
        if self.workspace_root is None:
            with self.lock:
                workspace_still_used = any(
                    isinstance(row, dict)
                    and self._normalize_workspace_id(row.get("workspace_id"), row_id) == workspace_id
                    for row_id, row in self.session_index.items()
                )
            retained_root = self.root / workspace_id
            if not workspace_still_used and (retained_root / ".workspace_retained").exists():
                shutil.rmtree(retained_root, ignore_errors=True)
        return True

    def _user_profile_is_runnable(self, profile: dict) -> bool:
        if not isinstance(profile, dict):
            return False
        provider = str(profile.get("provider", "") or "").strip().lower()
        model = str(profile.get("model", "") or "").strip()
        if provider in {"", "unknown", "config_only"}:
            return False
        if not model:
            return False
        if provider == "ollama":
            base = str(profile.get("base_url", self.ollama_base) or self.ollama_base).strip()
            return bool(base)
        if is_openai_compat_provider(provider):
            endpoint = str(profile.get("endpoint", "") or "").strip()
            base = str(profile.get("base_url", "") or "").strip()
            return bool(endpoint or complete_chat_endpoint(base))
        if provider == "custom_http":
            return bool(str(profile.get("endpoint", "") or "").strip())
        if provider == "anthropic":
            api_key = str(profile.get("api_key", "") or "").strip()
            endpoint = str(profile.get("endpoint", "") or "").strip()
            base = str(profile.get("base_url", "") or "").strip()
            return bool(api_key and (endpoint or base))
        return False

    def _option_is_runnable(self, option: dict) -> bool:
        if not isinstance(option, dict):
            return False
        pid = str(option.get("profile_id", "") or "")
        profile = dict(self.user_model_profiles.get(pid, {}))
        if option.get("provider") is not None:
            profile["provider"] = option.get("provider")
        if option.get("model") is not None:
            profile["model"] = option.get("model")
        if str(profile.get("provider", "")).lower() == "ollama" and not str(profile.get("base_url", "")).strip():
            profile["base_url"] = self.ollama_base
        return self._user_profile_is_runnable(profile)

    def _ensure_user_active_runnable(self):
        active = self._active_profile()
        if self._user_profile_is_runnable(active):
            return
        for pid, profile in self.user_model_profiles.items():
            if self._user_profile_is_runnable(profile):
                self.user_active_profile_id = pid
                return

    def _probe_user_active_capabilities(self, force_probe: bool = False):
        profile = self._active_profile()
        if not profile or not self._user_profile_is_runnable(profile):
            return
        client = OllamaClient(
            str(profile.get("base_url", self.ollama_base) or self.ollama_base),
            str(profile.get("model", self.model) or self.model),
            int(profile.get("request_timeout", DEFAULT_REQUEST_TIMEOUT) or DEFAULT_REQUEST_TIMEOUT),
            provider=str(profile.get("provider", "ollama") or "ollama"),
            endpoint=str(profile.get("endpoint", "") or ""),
            api_key=str(profile.get("api_key", "") or ""),
            headers=profile.get("headers", {}) if isinstance(profile.get("headers"), dict) else {},
            payload_template=str(profile.get("payload_template", "") or ""),
            thinking_stream=bool(profile.get("thinking_stream", False)),
            response_stream=bool(profile.get("response_stream", False)),
        )
        client.apply_profile(profile)
        client.set_telemetry(self.telemetry_callback, context_provider=lambda: {}, name="capability_probe")
        caps = client.probe_multimodal_capabilities(force=True if force_probe else False)
        merged = merge_multimodal_capabilities(
            merge_multimodal_capabilities(
                infer_model_multimodal_capabilities(str(profile.get("provider", "")), str(profile.get("model", ""))),
                parse_capability_overrides(profile.get("capabilities", {})),
            ),
            caps,
        )
        profile["capabilities"] = merged
        self.user_model_profiles[self.user_active_profile_id] = profile
        self._persist_user_prefs()
        probe_entry = client.probe_cache_entry()
        probe_details = probe_entry.get("details", {}) if isinstance(probe_entry, dict) else {}
        probe_updated_at = float(
            (probe_entry.get("updated_at", now_ts()) if isinstance(probe_entry, dict) else now_ts()) or now_ts()
        )
        for sess in self.sessions.values():
            if self.user_active_profile_id not in sess.model_profiles:
                continue
            row = dict(sess.model_profiles[self.user_active_profile_id])
            row["capabilities"] = merged
            sess.model_profiles[self.user_active_profile_id] = row
            cache_key = sess._profile_cache_key(row)
            sess.multimodal_capability_cache[cache_key] = {
                "capabilities": merged,
                "details": probe_details if isinstance(probe_details, dict) else {},
                "updated_at": probe_updated_at,
                "provider": str(row.get("provider", "")),
                "model": str(row.get("model", "")),
            }
            if sess.active_profile_id == self.user_active_profile_id:
                sess.ollama.apply_profile(row)
            sess.updated_at = now_ts()
            sess._persist()

    def model_catalog(self, force_probe: bool = False) -> dict:
        if force_probe:
            try:
                self._probe_user_active_capabilities(force_probe=True)
            except Exception:
                pass
        opts = []
        profiles_changed = False
        ollama_profile_id = ""
        ollama_base = self.ollama_base
        for pid, profile in sorted(self.user_model_profiles.items(), key=lambda x: x[0]):
            model = str(profile.get("model", "") or "")
            caps = merge_multimodal_capabilities(
                infer_model_multimodal_capabilities(str(profile.get("provider", "")), model),
                parse_capability_overrides(profile.get("capabilities", {})),
            )
            if (not ollama_profile_id) and str(profile.get("provider", "")).lower() == "ollama":
                ollama_profile_id = pid
                ollama_base = str(profile.get("base_url", ollama_base) or ollama_base)
            opts.append(
                {
                    "selection": f"{pid}::{model}",
                    "profile_id": pid,
                    "provider": profile.get("provider", "unknown"),
                    "model": model,
                    "label": f"{profile.get('label', pid)} | {model or '(no-model)'}",
                    "source": profile.get("source", ""),
                    "thinking_hint": bool(profile.get("thinking_hint", False)),
                    "thinking_stream": bool(profile.get("thinking_stream", False)),
                    "response_stream": bool(profile.get("response_stream", False)),
                    "effort": str(profile.get("effort", "") or ""),
                    "max_effort": str(profile.get("max_effort", "") or ""),
                    "reasoning_supported": (
                        profile.get("reasoning_supported")
                        if profile.get("reasoning_supported") is not None
                        else model_reasoning_style(
                            str(profile.get("provider", "")), model, caps
                        )
                        != "none"
                    ),
                    "reasoning_style": str(
                        profile.get("reasoning_style")
                        or model_reasoning_style(str(profile.get("provider", "")), model, caps)
                        or ""
                    ),
                    "display_name": str(profile.get("display_name", profile.get("label", pid)) or ""),
                    "title": str(profile.get("title", profile.get("label", pid)) or ""),
                    "capabilities": caps,
                }
            )
        if not ollama_profile_id:
            ollama_profile_id = "ollama"
        seen = {str(x.get("selection", "")) for x in opts}
        for pid, profile in sorted(self.user_model_profiles.items(), key=lambda x: x[0]):
            if str(profile.get("provider", "")).lower() != "ollama":
                continue
            base = str(profile.get("base_url", self.ollama_base) or self.ollama_base).strip()
            if not base:
                continue
            tags = list_ollama_models_cached(
                base,
                force_refresh=bool(force_probe),
                background=not force_probe,
            )
            ollama_records = probe_provider_models(
                profile,
                force_refresh=bool(force_probe),
                background=not force_probe,
            )
            profiles_changed = merge_probed_models_into_profile(
                profile, ollama_records, model_ids=tags
            ) or profiles_changed
            ollama_record_map = {
                str(record.get("id", "")): record
                for record in ollama_records
                if isinstance(record, dict) and str(record.get("id", "")).strip()
            }
            if tags:
                if pid == self.user_active_profile_id:
                    self.ollama_env_tags = list(tags)
            elif pid == self.user_active_profile_id and self.ollama_env_tags:
                tags = list(self.ollama_env_tags)
            for tag in tags:
                selection = f"{pid}::{tag}"
                if selection in seen:
                    continue
                seen.add(selection)
                tag_caps = merge_multimodal_capabilities(
                    infer_model_multimodal_capabilities("ollama", tag),
                    parse_capability_overrides(profile.get("capabilities", {})),
                )
                tag_record = ollama_record_map.get(tag)
                tag_record_caps = (
                    tag_record.get("capabilities", {})
                    if isinstance(tag_record, dict)
                    else {}
                )
                tag_record_probed = isinstance(tag_record, dict)
                opts.append(
                    {
                        "selection": selection,
                        "profile_id": pid,
                        "provider": "ollama",
                        "model": tag,
                        "label": f"{profile.get('label', 'Ollama')} | {tag}",
                        "source": "ollama-tags",
                        "thinking_hint": bool(profile.get("thinking_hint", self.thinking)),
                        "thinking_stream": bool(profile.get("thinking_stream", False)),
                        "response_stream": bool(profile.get("response_stream", False)),
                        "effort": str(profile.get("effort", "") or ""),
                        "max_effort": str(profile.get("max_effort", "") or ""),
                        "reasoning_supported": (
                            profile.get("reasoning_supported")
                            if profile.get("reasoning_supported") is not None
                            else tag_record_caps.get("reasoning_supported")
                            if isinstance(tag_record_caps, dict)
                            and tag_record_caps.get("reasoning_supported") is not None
                            else model_reasoning_style(
                                "ollama",
                                tag,
                                tag_caps,
                                capabilities_probed=tag_record_probed,
                            )
                            != "none"
                        ),
                        "reasoning_style": str(
                            profile.get("reasoning_style")
                            or tag_record_caps.get("reasoning_style", "")
                            or model_reasoning_style(
                                "ollama",
                                tag,
                                tag_caps,
                                capabilities_probed=tag_record_probed,
                            )
                            or ""
                        ),
                        "display_name": str(profile.get("display_name", profile.get("label", pid)) or ""),
                        "title": str(profile.get("title", profile.get("label", pid)) or ""),
                        "capabilities": tag_caps,
                    }
                )
        for pid, profile in sorted(self.user_model_profiles.items(), key=lambda x: x[0]):
            configured = [str(x).strip() for x in profile.get("models", []) if str(x).strip()]
            records = probe_provider_models(
                profile,
                force_refresh=bool(force_probe),
                background=not force_probe,
            )
            profiles_changed = merge_probed_models_into_profile(profile, records) or profiles_changed
            for rec in records:
                model_id = str(rec.get("id", "") or "").strip()
                if model_id and model_id not in configured:
                    configured.append(model_id)
            for model_id in configured:
                selection = f"{pid}::{model_id}"
                if not model_id or selection in seen:
                    continue
                seen.add(selection)
                rec = next((r for r in records if str(r.get("id", "")) == model_id), {})
                rcaps = rec.get("capabilities", {}) if isinstance(rec, dict) else {}
                opts.append({
                    "selection": selection, "profile_id": pid,
                    "provider": profile.get("provider", "unknown"), "model": model_id,
                    "label": f"{profile.get('label', pid)} | {model_id}",
                    "source": "provider-probe" if rec else profile.get("source", ""),
                    "thinking_hint": bool(profile.get("thinking_hint", False)),
                    "thinking_stream": bool(profile.get("thinking_stream", False)),
                    "response_stream": bool(profile.get("response_stream", False)),
                    "effort": str(profile.get("effort", "") or ""),
                    "max_effort": str(profile.get("max_effort", "") or ""),
                    "reasoning_supported": (
                        rcaps.get("reasoning_supported")
                        if isinstance(rcaps, dict) and rcaps.get("reasoning_supported") is not None
                        else profile.get("reasoning_supported")
                        if profile.get("reasoning_supported") is not None
                        else model_reasoning_style(
                            str(profile.get("provider", "")),
                            model_id,
                            rcaps if isinstance(rcaps, dict) else None,
                            capabilities_probed=bool(rec),
                        )
                        != "none"
                    ),
                    "reasoning_style": str(
                        (rcaps.get("reasoning_style") if isinstance(rcaps, dict) else "")
                        or profile.get("reasoning_style", "")
                        or model_reasoning_style(
                            str(profile.get("provider", "")),
                            model_id,
                            rcaps if isinstance(rcaps, dict) else None,
                            capabilities_probed=bool(rec),
                        )
                        or ""
                    ),
                    "display_name": str(profile.get("display_name", profile.get("label", pid)) or ""),
                    "title": str(profile.get("title", profile.get("label", pid)) or ""),
                    "capabilities": merge_multimodal_capabilities(infer_model_multimodal_capabilities(str(profile.get("provider", "")), model_id), parse_capability_overrides(profile.get("capabilities", {}))),
                })
        for _option in opts:
            _pid = str(_option.get("profile_id", "") or "")
            _profile = self.user_model_profiles.get(_pid, {})
            apply_model_option_runtime_fields(_option, _profile, str(_option.get("model", "") or ""))
        runnable_opts = [x for x in opts if self._option_is_runnable(x)]
        if runnable_opts:
            opts = runnable_opts
        active = self.user_model_profiles.get(self.user_active_profile_id, {})
        selected = f"{self.user_active_profile_id}::{active.get('model','')}" if active else ""
        option_map = {str(x.get("selection", "")) for x in opts}
        if active and selected and selected not in option_map:
            active_caps = merge_multimodal_capabilities(
                infer_model_multimodal_capabilities(str(active.get("provider", "")), str(active.get("model", ""))),
                parse_capability_overrides(active.get("capabilities", {})),
            )
            opts.insert(
                0,
                {
                    "selection": selected,
                    "profile_id": self.user_active_profile_id,
                    "provider": active.get("provider", "unknown"),
                    "model": str(active.get("model", "") or ""),
                    "label": f"{active.get('label', self.user_active_profile_id)} | {str(active.get('model', '') or '(no-model)')}",
                    "source": active.get("source", "active-profile"),
                    "thinking_hint": bool(active.get("thinking_hint", False)),
                    "thinking_stream": bool(active.get("thinking_stream", False)),
                    "response_stream": bool(active.get("response_stream", False)),
                    "effort": str(active.get("effort", "") or ""),
                    "max_effort": str(active.get("max_effort", "") or ""),
                    "reasoning_supported": (
                        active.get("reasoning_supported")
                        if active.get("reasoning_supported") is not None
                        else model_reasoning_style(
                            str(active.get("provider", "")),
                            str(active.get("model", "") or ""),
                            active.get("capabilities", {}),
                        )
                        != "none"
                    ),
                    "reasoning_style": str(
                        active.get("reasoning_style")
                        or model_reasoning_style(
                            str(active.get("provider", "")),
                            str(active.get("model", "") or ""),
                            active.get("capabilities", {}),
                        )
                        or ""
                    ),
                    "capabilities": active_caps,
                },
            )
            apply_model_option_runtime_fields(opts[0], active, str(active.get("model", "") or ""))
            option_map.add(selected)
        if opts and selected not in option_map:
            selected = str(opts[0].get("selection", ""))
        active_caps = merge_multimodal_capabilities(
            infer_model_multimodal_capabilities(str(active.get("provider", "")), str(active.get("model", ""))),
            parse_capability_overrides(active.get("capabilities", {})),
        )
        if profiles_changed:
            self._persist_user_prefs()
        return {
            "provider": active.get("provider", "ollama"),
            "models": [x["selection"] for x in opts] or [self.model],
            "options": opts,
            "selected": selected,
            "thinking": self.thinking,
            "response_stream": bool(active.get("response_stream", False)),
            "thinking_mode": "auto",
            "active_capabilities": active_caps,
        }

    def set_runtime_model(self, model: str, thinking: bool | None = None, settings: dict | None = None) -> dict:
        raw = str(model or "").strip()
        if not raw:
            raise ValueError("model required")
        explicit_profile = "::" in raw
        if "::" in raw:
            pid, selected_model = raw.split("::", 1)
        else:
            pid, selected_model = self.user_active_profile_id, raw
        pid = sanitize_profile_id(pid)
        with self.lock:
            profile = dict(self.user_model_profiles.get(pid, {}))
            if not profile:
                if pid.startswith("ollama"):
                    profile = {
                        "id": pid,
                        "provider": "ollama",
                        "label": "Ollama",
                        "model": selected_model or self.model,
                        "base_url": self.ollama_base,
                        "capabilities": infer_model_multimodal_capabilities("ollama", selected_model or self.model),
                        "media_endpoints": {},
                        "source": "runtime",
                    }
                else:
                    raise ValueError(f"profile not found: {pid}")
            if selected_model.strip():
                profile["model"] = selected_model.strip()
            profile = apply_model_runtime_settings(profile, str(profile.get("model", "") or ""), settings)
            for record in probe_provider_models(profile, background=True):
                if str(record.get("id", "")) == str(profile.get("model", "")):
                    merge_probed_models_into_profile(profile, [record])
                    break
            if str(profile.get("provider", "")).lower() == "ollama" and selected_model.strip():
                profile["capabilities"] = infer_model_multimodal_capabilities("ollama", selected_model.strip())
            if not self._user_profile_is_runnable(profile) and not explicit_profile and selected_model.strip():
                fallback_pid = ""
                for xpid, xprofile in self.user_model_profiles.items():
                    if str(xprofile.get("provider", "")).lower() == "ollama" and self._user_profile_is_runnable(xprofile):
                        fallback_pid = xpid
                        break
                if not fallback_pid:
                    for xpid, xprofile in self.user_model_profiles.items():
                        if self._user_profile_is_runnable(xprofile):
                            fallback_pid = xpid
                            break
                if fallback_pid:
                    pid = fallback_pid
                    profile = dict(self.user_model_profiles[fallback_pid])
                    profile["model"] = selected_model.strip()
            if not self._user_profile_is_runnable(profile):
                provider = str(profile.get("provider", "") or "unknown")
                model_text = str(profile.get("model", "") or "")
                raise ValueError(
                    f"profile '{pid}' is not runnable (provider={provider}, model={model_text or '(empty)'})"
                )
            profile["id"] = pid
            profile["selection"] = f"{pid}::{profile.get('model','')}"
            self.user_model_profiles[pid] = profile
            self.user_active_profile_id = pid
            self._sync_ollama_defaults(profile)
            self.thinking = False
            try:
                self._probe_user_active_capabilities(force_probe=False)
            except Exception:
                pass
            self._persist_user_prefs()
            for sess in self.sessions.values():
                try:
                    self._set_session_profile(sess, pid, profile)
                except Exception:
                    sess.ollama.model = self.model
                    sess.thinking = False
                    sess.updated_at = now_ts()
                    sess._persist()
            return self.model_catalog()

    def apply_llm_config(self, session_id: str, config: dict, source: str = "") -> dict:
        with self.lock:
            sess = self._load_session_locked(session_id)
            if not sess:
                raise KeyError(session_id)
            catalog = sess.load_llm_config(config, source=source)
            if bool(getattr(self, "web_search_setting_locked", False)):
                set_web_search_enabled_on_runtime(sess, self.web_search_enabled, persist=True)
            self._sync_from_session(sess, apply_to_all=True)
            return catalog

    def reset_to_llm_config(self, config: dict, source: str = "") -> dict:
        cfg = dict(config or {})
        OllamaClient.clear_global_probe_cache()
        profiles, active = self._profiles_from_config(cfg)
        probe_and_merge_model_profiles(profiles, force_refresh=True)
        with self.lock:
            normalized: dict[str, dict] = {}
            for pid, row in profiles.items():
                item = dict(row)
                item["id"] = sanitize_profile_id(str(pid))
                item["selection"] = f"{item['id']}::{item.get('model','')}"
                if source:
                    item["source"] = source
                normalized[item["id"]] = item
            self.default_llm_config = cfg
            self.user_model_profiles = normalized or self.user_model_profiles
            if active in self.user_model_profiles:
                self.user_active_profile_id = active
            elif self.user_model_profiles:
                self.user_active_profile_id = next(iter(self.user_model_profiles.keys()))
            self._ensure_user_ollama_profile()
            self._preflight_user_ollama_profile()
            self._ensure_user_active_runnable()
            active_profile = self._active_profile()
            self._sync_ollama_defaults(active_profile)
            self.thinking = False
            if _single_no_plan_todo_setting_present(cfg):
                _single_todo_enabled, _single_todo_prompt = extract_single_no_plan_todo_settings(cfg)
                self.single_no_plan_todo_enabled = bool(_single_todo_enabled)
                self.single_no_plan_todo_prompt = str(_single_todo_prompt or "").strip()
            cfg_read_context_policy = extract_read_context_policy_setting(cfg)
            if cfg_read_context_policy:
                self.read_context_policy = cfg_read_context_policy
            cfg_tool_memory_policy = extract_tool_memory_policy_setting(cfg)
            if cfg_tool_memory_policy:
                self.tool_memory_policy = cfg_tool_memory_policy
            cfg_auto_task_level_ceiling = extract_auto_task_level_ceiling_setting(cfg)
            if cfg_auto_task_level_ceiling is not None:
                self.auto_task_level_ceiling = normalize_auto_task_level_ceiling(cfg_auto_task_level_ceiling)
            cfg_l2_todo_policy = extract_l2_todo_policy_setting(cfg)
            if cfg_l2_todo_policy is not None:
                self.l2_todo_policy = normalize_l2_todo_policy(cfg_l2_todo_policy)
            cfg_web_search_enabled = extract_web_search_enabled_setting(cfg)
            if cfg_web_search_enabled is not None and not bool(getattr(self, "web_search_setting_locked", False)):
                self.web_search_enabled = bool(cfg_web_search_enabled)
            cfg_user_memory_mode = extract_user_memory_mode_setting(cfg)
            if cfg_user_memory_mode is not None and not bool(getattr(self, "user_memory_setting_locked", False)):
                self.user_memory_mode = normalize_user_memory_mode(cfg_user_memory_mode)
            self._persist_user_prefs()
            for sess in self.sessions.values():
                self._apply_user_defaults_to_session(sess, clear_cap_cache=True)
        return self.model_catalog()

    def set_user_language(self, language: str) -> dict:
        lang = normalize_ui_language(language)
        with self.lock:
            self.user_language = lang
            self._persist_user_prefs()
        return {"ok": True, "language": lang, "existing_sessions_unchanged": True}

    def set_session_language(self, session_id: str, language: str, set_user_default: bool = False) -> dict:
        lang = normalize_ui_language(language)
        with self.lock:
            sess = self._load_session_locked(session_id)
            if not sess:
                raise KeyError(session_id)
            sess._set_ui_language(lang, relabel_todos=True)
            sess.updated_at = now_ts()
            sess._persist()
            row = dict(self.session_index.get(sess.id, {}))
            row.update({
                "id": sess.id,
                "title": str(getattr(sess, "title", sess.id) or sess.id),
                "ui_language": normalize_ui_language(getattr(sess, "ui_language", lang)),
                "updated_at": float(getattr(sess, "updated_at", now_ts()) or now_ts()),
                "message_count": int(self._session_message_count(sess)),
                "loaded": True,
            })
            self.session_index[sess.id] = row
            if set_user_default:
                self.user_language = lang
                self._persist_user_prefs()
        return {"ok": True, "session_id": session_id, "language": lang, "set_user_default": bool(set_user_default)}

    def import_default_llm_config(self, session_id: str) -> dict:
        cfg = parse_json_object(try_read_text(LLM_CONFIG_PATH) or "{}", {})
        if not cfg:
            raise FileNotFoundError(f"missing or invalid config: {LLM_CONFIG_PATH}")
        return self.apply_llm_config(session_id, cfg, source=str(LLM_CONFIG_PATH))

    def list(self, *, limit: int | None = None, offset: int = 0, search: str = "", status: str = "") -> list[dict] | dict:
        needle = str(search or "").strip().lower()
        status_key = str(status or "").strip().lower()

        def public_row(raw: dict) -> dict:
            sid = str(raw.get("id", "") or "")
            title = str(raw.get("title", "") or sid)
            return {
                "id": sid,
                "workspace_id": self._normalize_workspace_id(raw.get("workspace_id"), sid),
                "title": title,
                "created_at": float(raw.get("created_at", 0.0) or 0.0),
                "running": bool(raw.get("running", False)),
                "degraded": bool(raw.get("degraded", False)),
                "recovered_at": float(raw.get("recovered_at", 0.0) or 0.0),
                "recovered_reason": str(raw.get("recovered_reason", "") or ""),
                "ui_language": normalize_ui_language(raw.get("ui_language", self.user_language)),
                "updated_at": float(raw.get("updated_at", 0.0) or 0.0),
                "message_count": int(raw.get("message_count", 0) or 0),
                "kernel_version": str(raw.get("kernel_version", "") or ""),
            }

        off = max(0, int(offset or 0))
        lim = max(1, min(2000, int(limit or SESSION_LIST_DEFAULT_LIMIT))) if limit is not None else 0
        plain_catalog = not needle and status_key not in {"running", "active", "idle", "stopped"}
        with self.lock:
            catalog_revision = int(getattr(self, "catalog_revision", 0) or 0)
            if plain_catalog and limit is not None:
                selected, total = self._session_catalog_page_locked(off, lim)
                catalog_rows = []
            else:
                catalog_rows = self._session_catalog_rows_locked()
                total = len(catalog_rows)
                selected = catalog_rows if limit is None else catalog_rows[off: off + lim]
        if plain_catalog:
            filtered_rows = [public_row(raw) for raw in selected]
        else:
            matched: list[dict] = []
            for raw in catalog_rows:
                sid = str(raw.get("id", "") or "")
                title = str(raw.get("title", "") or sid)
                running = bool(raw.get("running", False))
                if needle and needle not in title.lower() and needle not in sid.lower():
                    continue
                if status_key in {"running", "active"} and not running:
                    continue
                if status_key in {"idle", "stopped"} and running:
                    continue
                matched.append(raw)
            total = len(matched)
            selected = matched if limit is None else matched[off: off + lim]
            filtered_rows = [public_row(raw) for raw in selected]
        if limit is None:
            return filtered_rows
        page_rows = filtered_rows
        with self.lock:
            loaded_by_id = {
                str(row.get("id", "") or ""): self.sessions.get(str(row.get("id", "") or ""))
                for row in page_rows
            }
        for row in page_rows:
            sess = loaded_by_id.get(str(row.get("id", "") or ""))
            if sess is None:
                continue
            row.update(
                {
                    "workspace_id": str(getattr(sess, "workspace_id", row.get("workspace_id", sess.id)) or sess.id),
                    "title": str(getattr(sess, "title", row.get("title", "")) or row.get("title", "")),
                    "running": bool(getattr(sess, "running", False) or getattr(sess, "scheduler_starting", False)),
                    "degraded": False,
                    "recovered_at": float(getattr(sess, "run_recovered_at", 0.0) or 0.0),
                    "recovered_reason": str(getattr(sess, "run_recovered_reason", "") or ""),
                    "ui_language": normalize_ui_language(getattr(sess, "ui_language", row.get("ui_language", self.user_language))),
                    "created_at": float(getattr(sess, "created_at", row.get("created_at", 0.0)) or 0.0),
                    "updated_at": float(getattr(sess, "updated_at", row.get("updated_at", 0.0)) or 0.0),
                    "message_count": int(row.get("message_count", 0) or 0),
                    "kernel_version": str(getattr(sess, "kernel_version", row.get("kernel_version", "")) or ""),
                }
            )
        with self.lock:
            workspace_counts: dict[str, int] = {}
            workspace_meta: dict[str, dict] = {}
            for session_id, raw in self.session_index.items():
                if not isinstance(raw, dict):
                    continue
                wid = self._normalize_workspace_id(raw.get("workspace_id"), session_id)
                workspace_counts[wid] = workspace_counts.get(wid, 0) + 1
                created = float(raw.get("created_at", 0.0) or 0.0)
                if created <= 0:
                    created = float(raw.get("updated_at", 0.0) or 0.0)
                title = str(raw.get("title", "") or session_id).strip() or session_id
                prior = workspace_meta.get(wid)
                if prior is None or created < float(prior.get("created_at", 0.0) or 0.0):
                    workspace_meta[wid] = {
                        "name": title,
                        "created_at": created,
                    }
            duplicate_names: dict[str, int] = {}
            for meta in workspace_meta.values():
                key = str(meta.get("name", "") or "").casefold()
                duplicate_names[key] = duplicate_names.get(key, 0) + 1
            workspace_labels: dict[str, str] = {}
            for wid, meta in workspace_meta.items():
                name = str(meta.get("name", "") or wid)
                created = float(meta.get("created_at", 0.0) or 0.0)
                label = name
                if duplicate_names.get(name.casefold(), 0) > 1 and created > 0:
                    try:
                        label = f"{name} · {datetime.fromtimestamp(created).strftime('%Y-%m-%d')}"
                    except Exception:
                        label = name
                workspace_labels[wid] = label
        for row in page_rows:
            wid = self._normalize_workspace_id(row.get("workspace_id"), str(row.get("id", "") or ""))
            meta = workspace_meta.get(wid, {})
            workspace_name = str(meta.get("name", "") or row.get("title", "") or row.get("id", ""))
            row["workspace_session_count"] = int(workspace_counts.get(wid, 1))
            row["workspace_name"] = workspace_name
            row["workspace_created_at"] = float(meta.get("created_at", row.get("created_at", 0.0)) or 0.0)
            row["workspace_label"] = workspace_labels.get(wid, workspace_name)
        return {
            "sessions": page_rows,
            "total": total,
            "offset": off,
            "limit": lim,
            "has_more": off + len(page_rows) < total,
            "catalog_revision": catalog_revision,
        }

    def workspace_history(self, session_id: str, *, limit: int = 60) -> dict:
        sid = str(session_id or "").strip()
        lim = max(0, min(120, int(limit or 0)))
        with self.lock:
            active = self.sessions.get(sid)
            source = self.session_index.get(sid)
            if active is None and not isinstance(source, dict):
                raise KeyError(sid)
            workspace_id = self._normalize_workspace_id(
                getattr(active, "workspace_id", "") if active is not None else source.get("workspace_id"),
                sid,
            )
            matches: list[dict] = []
            workspace_first: dict | None = None
            for raw in self.session_index.values():
                if not isinstance(raw, dict):
                    continue
                row_id = str(raw.get("id", "") or "").strip()
                if not row_id:
                    continue
                loaded = self.sessions.get(row_id)
                row_workspace_id = self._normalize_workspace_id(
                    getattr(loaded, "workspace_id", "") if loaded is not None else raw.get("workspace_id"),
                    row_id,
                )
                if row_workspace_id != workspace_id:
                    continue
                row_created_at = float(
                    raw.get("created_at", 0.0)
                    or (getattr(loaded, "created_at", 0.0) if loaded is not None else 0.0)
                    or raw.get("updated_at", 0.0)
                    or 0.0
                )
                row_title = str(
                    getattr(loaded, "title", "") if loaded is not None else raw.get("title", row_id)
                ) or row_id
                first_created_at = float((workspace_first or {}).get("created_at", 0.0) or 0.0)
                if (
                    workspace_first is None
                    or (row_created_at > 0 and (first_created_at <= 0 or row_created_at < first_created_at))
                ):
                    workspace_first = {"title": row_title, "created_at": row_created_at}
                row = {
                    "id": row_id,
                    "workspace_id": row_workspace_id,
                    "title": str(
                        getattr(loaded, "title", "") if loaded is not None else raw.get("title", row_id)
                    )
                    or row_id,
                    "running": bool(
                        (getattr(loaded, "running", False) or getattr(loaded, "scheduler_starting", False))
                        if loaded is not None
                        else raw.get("running", False)
                    ),
                    "updated_at": float(
                        getattr(loaded, "updated_at", 0.0) if loaded is not None else raw.get("updated_at", 0.0)
                    ),
                    "created_at": row_created_at,
                    "workspace_name": str((workspace_first or {}).get("title", "") or row_title),
                    "workspace_created_at": float((workspace_first or {}).get("created_at", 0.0) or 0.0),
                    "message_count": max(0, int(raw.get("message_count", 0) or 0)),
                    "current": row_id == sid,
                }
                matches.append(row)
            matches.sort(key=lambda row: float(row.get("updated_at", 0.0) or 0.0), reverse=True)
            catalog_revision = int(getattr(self, "catalog_revision", 0) or 0)
            workspace_name = str((workspace_first or {}).get("title", "") or sid)
            workspace_created_at = float((workspace_first or {}).get("created_at", 0.0) or 0.0)
            for row in matches:
                row["workspace_name"] = workspace_name
                row["workspace_created_at"] = workspace_created_at
        total = len(matches)
        for row in matches:
            row["workspace_session_count"] = total
            row["workspace_label"] = workspace_name
        return {
            "ok": True,
            "session_id": sid,
            "workspace_id": workspace_id,
            "workspace_name": workspace_name,
            "workspace_created_at": workspace_created_at,
            "sessions": matches[:lim] if lim else [],
            "total": total,
            "has_history": total > 1,
            "truncated": bool(lim and total > lim),
            "catalog_revision": catalog_revision,
        }
